 void OpenOutput(){if(!Directory.Exists(output.Text))throw new Exception("Build a package first, or load an existing build.");Process.Start(new ProcessStartInfo(output.Text){UseShellExecute=true});}
 void LoadBuild(){using(var d=new FolderBrowserDialog{Description="Choose a completed Radio Studio build folder."}){if(d.ShowDialog()!=DialogResult.OK)return;if(!File.Exists(Path.Combine(d.SelectedPath,"checksums.json")))throw new Exception("This folder does not contain a completed build.");automaticOutput=false;output.Text=d.SelectedPath;string info=Path.Combine(d.SelectedPath,"station.json");if(File.Exists(info)){var package=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(info));int slot=Convert.ToInt32(package["slot"]);station.SelectedItem=definitions.FirstOrDefault(x=>x.slot==slot);}explicitBuild=true;UpdateSummary();}}
 void AutoOutput(){if(!automaticOutput||output==null||busy)return;string label=string.IsNullOrWhiteSpace(name.Text)?"My station":name.Text;foreach(char c in Path.GetInvalidFileNameChars())label=label.Replace(c,'-');label=label.Trim().TrimEnd('.');if(label.Length>60)label=label.Substring(0,60);settingOutput=true;output.Text=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"FH2 Radio Builds",label+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));settingOutput=false;}
 void UpdateSelection(){if(grid==null||remove==null)return;int count=grid.SelectedRows.Count;shuffle.Enabled=!busy&&grid.Rows.Count>1;remove.Enabled=!busy&&count>0;preview.Enabled=!busy&&count==1;up.Enabled=!busy&&count==1&&grid.SelectedRows[0].Index>0;down.Enabled=!busy&&count==1&&grid.SelectedRows[0].Index<grid.Rows.Count-1;}
 bool HasPackage(){try{return File.Exists(Path.Combine(output.Text,"checksums.json"));}catch(ArgumentException){return false;}}
 bool ValidGame(){if(game==null)return false;try{return File.Exists(Path.Combine(game.Text,"media","audio","RadioInfo_EN.xml"))||File.Exists(Path.Combine(game.Text,"Mount","media","audio","RadioInfo_EN.xml"));}catch(ArgumentException){return false;}}
