 Station ManagerSelection(){return managerGrid!=null&&managerGrid.SelectedRows.Count>0?managerGrid.SelectedRows[0].Tag as Station:null;}
 void RefreshManager(){if(managerGrid==null||managerGrid.IsDisposed)return;var selected=ManagerSelection();int wanted=selected==null?6:selected.slot;managerGrid.Rows.Clear();foreach(var s in definitions){int row=managerGrid.Rows.Add(s.slot,s.name,s.currentName??s.name,s.status??"Not scanned",s.trackCount);managerGrid.Rows[row].Tag=s;if(s.slot==wanted)managerGrid.Rows[row].Selected=true;}RefreshManagerActions();}
 void RefreshManagerActions(){if(managerRestore==null)return;var selected=ManagerSelection();managerRestore.Enabled=!busy&&selected!=null&&selected.canRestore;managerRestoreAll.Enabled=!busy&&definitions.Any(x=>x.canRestore);if(selected!=null)managerHint.Text=selected.status=="Detected custom"?"Custom content detected without a recognised original backup. It is preserved when installing other slots.":selected.status=="Earlier install"?"An earlier install is detected. Its backups and current station will be imported automatically.":selected.canRestore?"This station can be restored independently. Other installed stations will stay in place.":"This slot is not managed. Install a package targeting this slot to customise it.";}
 void AddFolder(){using(var d=new FolderBrowserDialog{Description="Choose a folder of music. Files in subfolders are not included."}){if(d.ShowDialog()==DialogResult.OK)ImportDrop(new[]{d.SelectedPath});}}
 void ImportDrop(string[] paths){try{var files=new List<string>();foreach(var p in paths){if(Directory.Exists(p))files.AddRange(Directory.GetFiles(p).OrderBy(x=>x));else files.Add(p);}ImportFiles(files.Where(p=>new[]{".flac",".mp3",".wav",".m4a",".ogg",".opus",".aac"}.Contains(Path.GetExtension(p).ToLowerInvariant())).ToArray());}catch(Exception ex){Error(ex);}}

 Label Label(string text){return new Label{Text=text,UseMnemonic=false,AutoSize=true,ForeColor=ink,Margin=new Padding(0,2,0,0)};}
 TextBox Box(){return new TextBox{Dock=DockStyle.Fill,BackColor=surface,ForeColor=ink,BorderStyle=BorderStyle.FixedSingle,Margin=new Padding(0,2,0,2)};}
 Button Button(string text,Action action){var b=new Button{Text=text,AutoSize=true,MinimumSize=new Size(44,29),Height=30,Padding=new Padding(8,1,8,1),FlatStyle=FlatStyle.Flat,BackColor=surface,ForeColor=ink,Margin=new Padding(0,2,6,2)};b.FlatAppearance.BorderSize=1;b.FlatAppearance.BorderColor=Color.FromArgb(207,213,220);b.FlatAppearance.MouseOverBackColor=Color.FromArgb(229,234,239);b.Click+=delegate{try{action();}catch(Exception ex){Error(ex);}};return b;}
 Control Browse(TextBox box,bool folder,string filter="All files|*.*"){
  var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,Margin=Padding.Empty};p.RowStyles.Add(new RowStyle(SizeType.Percent,100));p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));p.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,82));p.Controls.Add(box,0,0);var b=Button("Browse",delegate{if(folder){using(var d=new FolderBrowserDialog()){if(Directory.Exists(box.Text))d.SelectedPath=box.Text;if(d.ShowDialog()==DialogResult.OK)box.Text=d.SelectedPath;}}else{using(var d=new OpenFileDialog{Filter=filter}){if(d.ShowDialog()==DialogResult.OK)box.Text=d.FileName;}}});b.AutoSize=false;b.MinimumSize=Size.Empty;b.Padding=Padding.Empty;b.Dock=DockStyle.Fill;b.Margin=new Padding(4,1,0,1);p.Controls.Add(b,1,0);return p;
 }
 TextBox ToolRow(TableLayoutPanel table,string title,string value){var row=new TableLayoutPanel{Dock=DockStyle.Top,Height=40,ColumnCount=2,Margin=Padding.Empty};row.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,155));row.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));row.Controls.Add(Label(title));var box=Box();box.Text=value;row.Controls.Add(Browse(box,false,"Executables|*.exe"),1,0);table.Controls.Add(row);return box;}
 void Error(Exception ex){Write(ex.Message);if(!logExpanded)ToggleLog();MessageBox.Show(this,ex.Message.Length>350?"The operation could not be completed. The activity log contains details.":ex.Message,"FH2 Radio Studio",MessageBoxButtons.OK,MessageBoxIcon.Error);}
 void Write(string text){if(IsDisposed)return;if(InvokeRequired){BeginInvoke((Action)(()=>Write(text)));return;}log.AppendText(text+Environment.NewLine);if(busy&&text.StartsWith("[PROGRESS] "))state.Text=text.Substring(11);}
 void SetBusy(bool value,string title,bool canCancel){busy=value;cancellable=canCancel;workspace.Enabled=projectBar.Enabled=pathControls.Enabled=!value;if(managerRestore!=null)managerRestore.Enabled=!value;if(managerRestoreAll!=null)managerRestoreAll.Enabled=!value;cancel.Enabled=value&&canCancel;cancel.Visible=value&&canCancel;progress.Visible=value;state.Text=title;UpdateSummary();RefreshManagerActions();}
 void Job(string title,bool canCancel,Action work,Action done=null){if(busy)return;SetBusy(true,title,canCancel);Task.Run(()=>{Exception failure=null;try{work();}catch(Exception ex){failure=ex;}BeginInvoke((Action)(()=>{SetBusy(false,failure==null?"Completed: "+title:"Operation failed. See log.",false);if(failure!=null)Error(failure);else if(done!=null)done();}));});}
 public static string Quote(string value){if(value==null)value="";var b=new System.Text.StringBuilder("\"");int slashes=0;foreach(char c in value){if(c=='\\'){slashes++;continue;}if(c=='"'){b.Append('\\',slashes*2+1);b.Append(c);}else{b.Append('\\',slashes);b.Append(c);}slashes=0;}b.Append('\\',slashes*2);b.Append('"');return b.ToString();}
 string Run(string executable,IEnumerable<string> arguments,bool echo){
  var info=new ProcessStartInfo(executable,string.Join(" ",arguments.Select(Quote))){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=System.Text.Encoding.UTF8,StandardErrorEncoding=System.Text.Encoding.UTF8,WorkingDirectory=root};
  using(var p=new Process{StartInfo=info}){var outputText=new System.Text.StringBuilder();var errors=new System.Text.StringBuilder();p.OutputDataReceived+=delegate(object s,DataReceivedEventArgs e){if(e.Data==null)return;lock(outputText)outputText.AppendLine(e.Data);if(echo)Write(e.Data);};p.ErrorDataReceived+=delegate(object s,DataReceivedEventArgs e){if(e.Data==null)return;lock(errors)errors.AppendLine(e.Data);if(echo)Write(e.Data);};p.Start();running=p;p.BeginOutputReadLine();p.BeginErrorReadLine();p.WaitForExit();running=null;if(p.ExitCode!=0)throw new Exception("Command failed ("+p.ExitCode+"): "+errors.ToString());return outputText.ToString();}
 }
 void CheckTools(){string n=node.Text,f=ffmpeg.Text,p=ffprobe.Text;Job("Checking audio tools",false,()=>{Run(n,new[]{"--version"},true);Run(f,new[]{"-version"},true);Run(p,new[]{"-version"},true);});}
 void Inspect(){string path=game.Text,tool=node.Text;int wanted=station.SelectedItem is Station?((Station)station.SelectedItem).slot:6;bool keepExplicit=explicitBuild;Discovery found=null;Job("Detecting installed stations",false,()=>{found=json.Deserialize<Discovery>(Run(Powershell,new[]{"-NoProfile","-ExecutionPolicy","Bypass","-File",Path.Combine(root,"runtime","Scan-Stations.ps1"),"-GameFolder",path},false));},()=>{definitions.Clear();definitions.AddRange(found.stations.Where(s=>s.available));station.Items.Clear();foreach(var s in definitions)station.Items.Add(s);station.SelectedItem=definitions.FirstOrDefault(s=>s.slot==wanted);if(station.SelectedIndex<0&&station.Items.Count>0)station.SelectedIndex=0;explicitBuild=keepExplicit;Write("Found "+definitions.Count+" stations; "+definitions.Count(x=>x.status!=null&&x.status!="Original")+" custom stations detected.");UpdateSummary();RefreshManager();});}
 void AddMusic(){using(var d=new OpenFileDialog{Multiselect=true,Filter="Audio|*.flac;*.mp3;*.wav;*.m4a;*.ogg;*.opus;*.aac"}){if(d.ShowDialog()==DialogResult.OK)ImportFiles(d.FileNames);}}
 void ImportFiles(string[] files){if(files.Length==0){state.Text="No supported audio files found.";return;}string probe=ffprobe.Text;var tracks=new List<Track>();Job("Reading track metadata",true,()=>{foreach(var file in files){var parsed=json.Deserialize<Dictionary<string,object>>(Run(probe,new[]{"-v","error","-show_entries","format=duration:format_tags=title,artist,album_artist","-of","json",file},false));var format=(Dictionary<string,object>)parsed["format"];var tags=format.ContainsKey("tags")?(Dictionary<string,object>)format["tags"]:new Dictionary<string,object>();double seconds=0;if(format.ContainsKey("duration"))double.TryParse(Convert.ToString(format["duration"]),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out seconds);tracks.Add(new Track{file=file,title=ReadTag(tags,"title",Path.GetFileNameWithoutExtension(file)),artist=ReadTag(tags,"artist",ReadTag(tags,"album_artist","Unknown artist")),duration=seconds});}},()=>{foreach(var t in tracks){if(grid.Rows.Cast<DataGridViewRow>().Any(r=>r.Tag is Track&&string.Equals(((Track)r.Tag).file,t.file,StringComparison.OrdinalIgnoreCase)))continue;AddRow(t);}UpdateSummary();});}
 static string ReadTag(Dictionary<string,object> tags,string key,string fallback){return tags.ContainsKey(key)?Convert.ToString(tags[key]):fallback;}
 void AddRow(Track t){int row=grid.Rows.Add(t.title,t.artist,TimeSpan.FromSeconds(Math.Max(0,t.duration)).ToString(@"mm\:ss"),Path.GetFileName(t.file));grid.Rows[row].Tag=t;}
 List<Track> ReadTracks(){grid.EndEdit();return grid.Rows.Cast<DataGridViewRow>().Where(r=>r.Tag is Track).Select(r=>new Track{file=((Track)r.Tag).file,duration=((Track)r.Tag).duration,title=Convert.ToString(r.Cells[0].Value),artist=Convert.ToString(r.Cells[1].Value)}).ToList();}
 void RemoveTracks(){foreach(var r in grid.SelectedRows.Cast<DataGridViewRow>().OrderByDescending(r=>r.Index))grid.Rows.Remove(r);UpdateSummary();}
 void MoveTrack(int delta){if(grid.SelectedRows.Count!=1)return;int index=grid.SelectedRows[0].Index,target=index+delta;if(target<0||target>=grid.Rows.Count)return;var tracks=ReadTracks();var t=tracks[index];tracks.RemoveAt(index);tracks.Insert(target,t);grid.Rows.Clear();foreach(var item in tracks)AddRow(item);grid.ClearSelection();grid.Rows[target].Selected=true;}
 static void RandomiseTracks(List<Track> tracks,Random random){for(int i=tracks.Count-1;i>0;i--){int j=random.Next(i+1);var item=tracks[i];tracks[i]=tracks[j];tracks[j]=item;}}
 void ShuffleTracks(){if(busy||grid.Rows.Count<2)return;var tracks=ReadTracks();RandomiseTracks(tracks,new Random());explicitBuild=false;grid.Rows.Clear();foreach(var item in tracks)AddRow(item);grid.ClearSelection();UpdateSummary();state.Text="Track list shuffled. Rebuild, then update this station to apply it.";}
 void Preview(){if(grid.SelectedRows.Count==1)Process.Start(new ProcessStartInfo(((Track)grid.SelectedRows[0].Tag).file){UseShellExecute=true});}
 void UpdateSummary(){if(grid==null||summary==null)return;var selected=station.SelectedItem as Station;int count=grid.Rows.Count;double seconds=grid.Rows.Cast<DataGridViewRow>().Where(r=>r.Tag is Track).Sum(r=>((Track)r.Tag).duration);summary.Text=count==0?"No tracks added":count+" / "+(selected==null?20:selected.maxTracks)+" tracks   |   "+TimeSpan.FromSeconds(seconds).ToString(@"hh\:mm\:ss")+"   |   About "+(seconds*192000/1048576).ToString("N0")+" MiB";bool over=selected!=null&&count>selected.maxTracks;summary.ForeColor=over?Color.FromArgb(153,52,48):muted;emptyState=count==0;empty.Visible=emptyState;if(empty.Visible)empty.BringToFront();if(build==null)return;bool valid=ValidGame(),ready=HasPackage(),backup=HasBackup();bool current=explicitBuild||(builtFingerprint!=null&&builtFingerprint==Fingerprint(CurrentForFingerprint()));build.Enabled=!busy&&valid&&!string.IsNullOrWhiteSpace(name.Text)&&count>0&&!over;build.BackColor=build.Enabled?accent:Color.FromArgb(230,234,239);build.ForeColor=build.Enabled?Color.White:muted;build.FlatAppearance.BorderColor=build.Enabled?accent:Color.FromArgb(207,213,220);install.Enabled=!busy&&valid&&ready&&current;install.Text=backup?"Update station":"Install in game";restore.Enabled=!busy&&valid&&backup;gameHint.Text=valid?"Game found; "+definitions.Count(x=>x.status!=null&&x.status!="Original")+" custom station(s).":"Choose your FH2 game folder.";if(!busy)packageHint.Text=ready&&!current?"Choose a new folder to build these settings, or use Load build to select an existing package.":ready&&backup?"This slot already has a custom station. Installing updates this slot only.":ready?"Package selected. Other custom stations will stay installed.":over?"Too many tracks for this station. Remove tracks or select another slot.":!valid?"Start by choosing your FH2 game folder.":count==0?"Add music to prepare your station.":"Build a package, then install it with Azimuth closed.";UpdateSelection();}
 void ShowArtwork(){if(artwork==null)return;try{if(artwork.Image!=null){var old=artwork.Image;artwork.Image=null;old.Dispose();}if(File.Exists(logo.Text)){using(var image=Image.FromFile(logo.Text))artwork.Image=new Bitmap(image);}}catch(Exception){}}
 Project ReadProject(){var s=station.SelectedItem as Station;return new Project{slot=s==null?6:s.slot,gameFolder=game.Text,stationName=name.Text,logoPath=logo.Text,outputFolder=output.Text,normalise=normalise.Checked,tools=new ToolPaths{node=node.Text,ffmpeg=ffmpeg.Text,ffprobe=ffprobe.Text,texconv=texconv.Text},tracks=ReadTracks()};}
 public void Apply(Project p){if(p==null||p.schema!=1||p.tracks==null||p.tools==null)throw new Exception("Unsupported or incomplete project.");game.Text=p.gameFolder;name.Text=p.stationName;logo.Text=p.logoPath;settingOutput=true;output.Text=p.outputFolder;settingOutput=false;automaticOutput=string.IsNullOrWhiteSpace(p.outputFolder);normalise.Checked=p.normalise;node.Text=p.tools.node;ffmpeg.Text=p.tools.ffmpeg;ffprobe.Text=p.tools.ffprobe;texconv.Text=p.tools.texconv=="texconv.exe"&&File.Exists(Path.Combine(root,"tools","bin","texconv.exe"))?Path.Combine(root,"tools","bin","texconv.exe"):p.tools.texconv;grid.Rows.Clear();foreach(var t in p.tracks)AddRow(t);if(definitions.Count==0){var path=Path.Combine(root,"tools","stations.json");definitions.AddRange(json.Deserialize<List<Station>>(File.ReadAllText(path)));foreach(var s in definitions){s.maxTracks=s.slot<=2?22:20;station.Items.Add(s);}}station.SelectedItem=definitions.FirstOrDefault(s=>s.slot==p.slot);AutoOutput();UpdateSummary();}
 bool ConfirmDiscard(){return (grid.Rows.Count==0&&string.IsNullOrWhiteSpace(name.Text)&&string.IsNullOrWhiteSpace(logo.Text))||MessageBox.Show("Discard the current unsaved project?","New project",MessageBoxButtons.YesNo)==DialogResult.Yes;}
 void OpenProject(){using(var d=new OpenFileDialog{Filter="Radio project|*.fh2radio.json;*.json"}){if(d.ShowDialog()!=DialogResult.OK)return;var p=json.Deserialize<Project>(File.ReadAllText(d.FileName));Apply(p);projectPath=d.FileName;Write("Loaded project "+Path.GetFileName(projectPath));Text="FH2 Radio Studio 0.3.1 - "+Path.GetFileName(projectPath);}}
 void SaveProject(){using(var d=new SaveFileDialog{Filter="Radio project|*.fh2radio.json",FileName=projectPath==null?"My station.fh2radio.json":Path.GetFileName(projectPath)}){if(d.ShowDialog()!=DialogResult.OK)return;File.WriteAllText(d.FileName,json.Serialize(ReadProject()),new System.Text.UTF8Encoding(false));projectPath=d.FileName;state.Text="Saved "+Path.GetFileName(projectPath);Text="FH2 Radio Studio 0.3.1 - "+Path.GetFileName(projectPath);}}
 void ChooseOutput(){using(var d=new FolderBrowserDialog{Description="Choose a parent folder; a new build subfolder will be created there."}){if(d.ShowDialog()==DialogResult.OK){automaticOutput=false;output.Text=Path.Combine(d.SelectedPath,"FH2-Radio-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));}}}
 string Powershell {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe");}}
 void Script(string path,string argument,string value){Run(Powershell,new[]{"-NoProfile","-ExecutionPolicy","Bypass","-File",path,argument,value},true);}
 Project CurrentForFingerprint(){var selected=station.SelectedItem as Station;return new Project{slot=selected==null?6:selected.slot,gameFolder=game.Text,stationName=name.Text,logoPath=logo.Text,outputFolder=output.Text,normalise=normalise.Checked,tracks=grid.Rows.Cast<DataGridViewRow>().Where(r=>r.Tag is Track).Select(r=>new Track{file=((Track)r.Tag).file,title=Convert.ToString(r.Cells[0].Value),artist=Convert.ToString(r.Cells[1].Value)}).ToList()};}
 string Fingerprint(Project p){return json.Serialize(new{p.slot,p.gameFolder,p.stationName,p.logoPath,p.outputFolder,p.normalise,tracks=p.tracks.Select(t=>new{t.file,t.title,t.artist}).ToArray()});}
 void Build(){if(Directory.Exists(output.Text)){string parent=Path.GetDirectoryName(Path.GetFullPath(output.Text));automaticOutput=false;output.Text=Path.Combine(parent,"FH2-Radio-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));}var p=ReadProject();if(string.IsNullOrWhiteSpace(p.stationName)||p.tracks.Count==0||string.IsNullOrWhiteSpace(p.outputFolder))throw new Exception("Choose a game folder, station name, music and a new output folder first.");string temporary=Path.Combine(Path.GetTempPath(),"fh2-studio-"+Guid.NewGuid().ToString("N")+".json"),work=Path.Combine(Path.GetTempPath(),"fh2-radio-build-"+Guid.NewGuid().ToString("N"));File.WriteAllText(temporary,json.Serialize(p),new System.Text.UTF8Encoding(false));Job("Building station",true,()=>{try{Run(Powershell,new[]{"-NoProfile","-ExecutionPolicy","Bypass","-File",Path.Combine(root,"Build-Radio.ps1"),"-ProjectFile",temporary,"-WorkFolder",work},true);}finally{File.Delete(temporary);if(Directory.Exists(work)&&string.Equals(Path.GetDirectoryName(Path.GetFullPath(work)),Path.GetTempPath().TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase)&&System.Text.RegularExpressions.Regex.IsMatch(Path.GetFileName(work),"^fh2-radio-build-[a-f0-9]{32}$")){try{Directory.Delete(work,true);}catch(IOException){Write("Temporary conversion files could not be removed: "+work);}}}},()=>{builtFingerprint=Fingerprint(p);explicitBuild=false;UpdateSummary();Write("Package ready. Close Azimuth, then choose Install in game.");});}
 void Install(){string folder=output.Text,path=game.Text;if(!File.Exists(Path.Combine(folder,"checksums.json")))throw new Exception("Select a completed build output folder first.");Job("Installing / updating station",false,()=>Run(Powershell,new[]{"-NoProfile","-ExecutionPolicy","Bypass","-File",Path.Combine(root,"runtime","Install.ps1"),"-GameFolder",path,"-PackageFolder",folder},true),Inspect);}
 void Restore(){var selected=station.SelectedItem as Station;if(selected==null||!selected.canRestore)throw new Exception("This slot has no recognised original backup.");RestoreSlot(selected.slot,false);}
 void RestoreSlot(int slot,bool all){string path=game.Text;Job(all?"Restoring all managed stations":"Restoring selected station",false,()=>{var arguments=new List<string>{"-NoProfile","-ExecutionPolicy","Bypass","-File",Path.Combine(root,"runtime","Uninstall.ps1"),"-GameFolder",path};if(all)arguments.Add("-All");else arguments.AddRange(new[]{"-Slot",slot.ToString()});Run(Powershell,arguments,true);},Inspect);}
 void Cancel(){var p=running;if(p==null)return;try{RunKill(p.Id);Write("Cancelled. An incomplete output folder may remain; choose a new output folder for your next build.");}catch(Exception ex){Write(ex.Message);}}
 static void RunKill(int id){using(var p=Process.Start(new ProcessStartInfo("taskkill.exe","/PID "+id+" /T /F"){UseShellExecute=false,CreateNoWindow=true}))p.WaitForExit();}
 void Snapshot(string directory,string filename){var canvas=Controls[0];Controls.Remove(canvas);canvas.Size=ClientSize;canvas.Visible=true;canvas.CreateControl();canvas.PerformLayout();Application.DoEvents();using(var image=new Bitmap(canvas.Width,canvas.Height)){canvas.DrawToBitmap(image,new Rectangle(0,0,canvas.Width,canvas.Height));image.Save(Path.Combine(directory,filename));}Controls.Add(canvas);}
 public void SelfTest(string directory){
  Directory.CreateDirectory(directory);Apply(new Project());if(!emptyState||build.Enabled||install.Enabled||restore.Enabled)throw new Exception("Empty-state actions are incorrect");if(mainLayout.RowStyles[3].Height!=0)throw new Exception("Log should be hidden initially");
  var sample=new Project{stationName="Example Radio",outputFolder=@"C:\Radio Builds\Example Radio",tracks=new List<Track>{new Track{file="sample.wav",title="Example track",artist="Example artist",duration=210},new Track{file="second.wav",title="Second track",artist="Another artist",duration=185}}};Apply(sample);
  if(station.SelectedItem==null||!station.Text.Contains("Ninja"))throw new Exception("Station selector not populated");if(ReadProject().tracks[0].title!="Example track"||emptyState)throw new Exception("Track list roundtrip failed");
  edit.Checked=true;if(grid.Columns[0].ReadOnly)throw new Exception("Metadata editor stayed locked");grid.Rows[0].Cells[0].Value="Title & \"quotes\" \u00a3";var saved=json.Deserialize<Project>(json.Serialize(ReadProject()));if(saved.tracks[0].title!=Convert.ToString(grid.Rows[0].Cells[0].Value))throw new Exception("Edited metadata lost");edit.Checked=false;if(!grid.Columns[0].ReadOnly)throw new Exception("Metadata editor stayed unlocked");
  grid.ClearSelection();grid.Rows[0].Selected=true;MoveTrack(1);if(ReadProject().tracks[1].file!="sample.wav")throw new Exception("Track ordering failed");Apply(sample);
  var shuffledSample=new Project{stationName="Shuffle test",tracks=Enumerable.Range(0,20).Select(i=>new Track{file="file-"+i,title="Title "+i,artist="Artist "+i,duration=30+i}).ToList()};Apply(shuffledSample);var ordered=ReadTracks();RandomiseTracks(ordered,new Random(17));if(ordered.Select(t=>t.file).SequenceEqual(shuffledSample.tracks.Select(t=>t.file)))throw new Exception("Shuffle did not randomise");foreach(var t in ordered){int index=int.Parse(t.file.Substring(5));if(t.title!="Title "+index||t.artist!="Artist "+index||t.duration!=30+index)throw new Exception("Shuffle separated metadata");}if(ordered.Select(t=>t.file).Distinct().Count()!=20)throw new Exception("Shuffle lost or duplicated songs");ShuffleTracks();if(!state.Text.Contains("Rebuild"))throw new Exception("Shuffle guidance missing");if(Icon==null)throw new Exception("Application icon missing");Apply(sample);
  Snapshot(directory,"radio-studio-preview.png");Size=new Size(1000,760);Snapshot(directory,"radio-studio-compact.png");if(output.Multiline)throw new Exception("Output path should be a single line");ToggleLog();Snapshot(directory,"radio-studio-log.png");ToggleLog();
  string fixture=Path.Combine(directory,"readiness-fixture"),mount=Path.Combine(fixture,"Mount"),audio=Path.Combine(mount,"media","audio"),package=Path.Combine(directory,"ready-build");Directory.CreateDirectory(audio);File.WriteAllText(Path.Combine(audio,"RadioInfo_EN.xml"),"fixture");Directory.CreateDirectory(package);File.WriteAllText(Path.Combine(package,"checksums.json"),"[]");game.Text=fixture;output.Text=package;explicitBuild=true;UpdateSummary();if(!build.Enabled||!install.Enabled||restore.Enabled)throw new Exception("Completed-package actions incorrect");name.Text="Edited station";if(install.Enabled)throw new Exception("Stale package should not be installed as an edited project");explicitBuild=true;UpdateSummary();Directory.CreateDirectory(Path.Combine(mount,"sadboys-worldwide-backup"));File.WriteAllText(Path.Combine(mount,"sadboys-worldwide-backup","restore.json"),"[]");UpdateSummary();((Station)station.SelectedItem).canRestore=true;UpdateSummary();if(!install.Enabled||!restore.Enabled)throw new Exception("Same-slot update actions incorrect");if(!definitions.Any(x=>x.canRestore))throw new Exception("Managed station restore not represented");SetBusy(true,"Test",true);if(build.Enabled||install.Enabled||restore.Enabled||shuffle.Enabled||pathControls.Enabled||!cancel.Enabled)throw new Exception("Busy-state actions incorrect");SetBusy(false,"Ready",false);
  File.WriteAllText(Path.Combine(directory,"ui-test.txt"),"PASS: empty state, project/metadata roundtrip, track ordering, shuffle permutation and metadata integrity, embedded icon, compact layout, log toggle, package readiness, existing backup and busy-state controls");Close();
 }
 [STAThread]public static void Main(string[] arguments){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var app=new Studio()){if(arguments.Length==2&&arguments[0]=="--self-test"){try{app.SelfTest(arguments[1]);}catch(Exception ex){Directory.CreateDirectory(arguments[1]);File.WriteAllText(Path.Combine(arguments[1],"ui-error.txt"),ex.ToString());Environment.ExitCode=1;}return;}Application.Run(app);}}
}
